 m=dict(points=normalize(p,list(vv.values())),edges=[],planar=True,bounds=[0,0,100,70],views=vv,checks=list(checks),description=f'Задача {n}'+('' if part=='single' else f' ({part})')+': собственный чертёж. Обоснования и вычисления находятся рядом.')
