def v395(x='X',m='M',n='N',radii=False):
 v=sc(['A','B','C',x,m,n]+(['O'] if radii else []),[['A','B'],['A','C'],[m,n]]+([['O',q] for q in ['B','C',x,m,n]] if radii else []),circles=[circle('O','B')])
 if radii:v['rightAngles']=[rt('O','B','A'),rt('O','C','A'),rt('O',x,m)]
